
<div class="heading"><div><h1>Registro de ventas</h1><small>Cada venta descuenta automáticamente las existencias.</small></div></div>
<div class="two-col"><div class="panel"><h3>Nueva venta</h3><form method="post"><?php csrf();?><input type="hidden" name="action" value="sale"><div class="form-grid"><label>Cliente<select name="client_id"><option value="">Consumidor final</option><?php foreach($clients as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Medio de pago<select name="payment_method"><option>Efectivo</option><option>Tarjeta</option><option>Transferencia</option></select></label></div><h3 style="margin-top:25px">Artículos</h3><div id="sale-lines"><div class="sale-row"><label>Producto<select name="product_id[]" required><?php foreach($products as $p):?><option value="<?=e($p['id'])?>" data-price="<?=e($p['price'])?>"><?=e($p['name'])?> · <?=money($p['price'])?> (<?=e($p['stock'])?> disponibles)</option><?php endforeach;?></select></label><label>Cantidad<input name="quantity[]" type="number" min="1" value="1" required></label><div></div><button type="button" class="secondary remove-line">×</button></div></div><template id="sale-template"><div class="sale-row"><label>Producto<select name="product_id[]" required><?php foreach($products as $p):?><option value="<?=e($p['id'])?>" data-price="<?=e($p['price'])?>"><?=e($p['name'])?> · <?=money($p['price'])?></option><?php endforeach;?></select></label><label>Cantidad<input name="quantity[]" type="number" min="1" value="1" required></label><div></div><button type="button" class="secondary remove-line">×</button></div></template><div class="form-actions"><button class="secondary" type="button" id="add-line">+ Agregar artículo</button><strong>Total estimado: <span id="sale-total">$0</span></strong></div><div class="form-actions"><button class="primary" type="submit" <?=!$products?'disabled':''?>>Confirmar venta</button></div></form></div><div class="panel"><h3>Historial de ventas</h3><div class="table-scroll"><table><thead><tr><th>ID</th><th>Cliente</th><th>Pago</th><th>Total</th><th>Fecha</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td>#<?=e($s['id'])?></td><td><?=e($s['client']?:'Consumidor final')?></td><td><?=e($s['payment_method'])?></td><td><?=money($s['total'])?></td><td><?=e($s['created_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$sales):?><p class="empty">Todavía no hay ventas.</p><?php endif;?></div></div></div>